import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"hnl_engine_exec_cranelift","description":"","frontmatter":{},"headers":[],"relativePath":"api/engine-exec-cranelift/hnl_engine_exec_cranelift/index.md","filePath":"api/engine-exec-cranelift/hnl_engine_exec_cranelift/index.md"}`),a={name:`api/engine-exec-cranelift/hnl_engine_exec_cranelift/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="hnl-engine-exec-cranelift" tabindex="-1">hnl_engine_exec_cranelift <a class="header-anchor" href="#hnl-engine-exec-cranelift" aria-label="Permalink to “hnl_engine_exec_cranelift”">​</a></h1><h1 id="hnl-engine-exec-cranelift-1" tabindex="-1">hnl-engine-exec-cranelift <a class="header-anchor" href="#hnl-engine-exec-cranelift-1" aria-label="Permalink to “hnl-engine-exec-cranelift”">​</a></h1><p>The <strong>cranelift eval engine</strong> for the eval operation (ADR-0044 §4, §7).</p><p>This engine compiles [<code>handl_language::Term</code>] data to <strong>native code</strong> via [cranelift] and executes it via an in-memory JIT. It shares the same <code>Term</code> vocabulary as the [<code>hnl_engine_exec_tree_walk</code>] reference interpreter and the <code>hnl_engine_exec_bytecode</code>(hnl_engine_exec_bytecode) bytecode engine; conformance tests verify all three produce <strong>identical results</strong>.</p><h2 id="compilation-strategy-boxed-values-native-control-flow" tabindex="-1">Compilation strategy: boxed values + native control flow <a class="header-anchor" href="#compilation-strategy-boxed-values-native-control-flow" aria-label="Permalink to “Compilation strategy: boxed values + native control flow”">​</a></h2><p>The handl value space is [<code>serde_json::Value</code>] — dynamically typed. A full type-inferred native compiler is out of scope for Phase 7. The realistic approach (and what ADR-0044 §7 &quot;compilers erase data dispatch&quot; means in practice):</p><p><strong>Cranelift generates native functions where:</strong></p><ul><li><strong>Control flow is native</strong>: [<code>Term::Choice</code>] compiles to native <code>brif</code>/<code>jump</code> instructions. <code>extend_env</code>/<code>proj_env</code> scope push/pop is native. [<code>Term::App</code>] closure dispatch is a native call to a helper.</li><li><strong>Value operations call Rust helpers</strong>: native <code>Arr</code> ops ([<code>Term::Arr</code>] with <code>ArrSource::Native</code>), foreign <code>Arr</code> ops ([<code>Term::Arr</code>] with <code>ArrSource::Foreign</code>), <code>proj_child</code>, variable load/store, and payload access are native calls into Rust functions that operate on [<code>Value</code>] (boxed as a pointer). The native code passes/receives <code>*mut Value</code> handles.</li><li><strong>The per-node scheme lookup is erased</strong>: at compile time, each node&#39;s [<code>Term</code>] is lowered to a fixed sequence of cranelift IR instructions + helper calls. The compiled function has no <code>lang.eval[node.kind]</code> hash lookup at execution time — the scheme is baked into the native code. This is the ADR §7 property.</li></ul><p>This is a legitimate JIT: native control flow + erased data dispatch + helper calls for value ops. It is faster than the bytecode VM (native jumps vs interpreted dispatch) and demonstrates the compilation pipeline that enables the self-hosting bootstrap (<code>compile(handlLanguage, native)</code>).</p><h2 id="per-node-compilation" tabindex="-1">Per-node compilation <a class="header-anchor" href="#per-node-compilation" aria-label="Permalink to “Per-node compilation”">​</a></h2><p>Every node in the [<code>Ast</code>] arena is compiled to its own native function with the signature <code>fn(*mut EvalCtx) -&gt; *mut Value</code>. The scheme for each node is resolved at <strong>compile time</strong> (one-time <code>lang.eval[node.kind]</code> lookup) and baked into the IR. At execution time, <code>proj_child</code> dispatches to the child&#39;s pre-compiled native function via a function-pointer cache — no scheme lookup occurs.</p><h2 id="constant-pools" tabindex="-1">Constant pools <a class="header-anchor" href="#constant-pools" aria-label="Permalink to “Constant pools”">​</a></h2><p>Literal values and string names (variable names, primitive operators, foreign function names) encountered during compilation are collected into constant pools stored in [<code>EvalCtx</code>]. The compiled code references them by index, avoiding raw string pointers in native code.</p><h2 id="conventions-matched-to-the-tree-walk-and-bytecode" tabindex="-1">Conventions (matched to the tree-walk and bytecode) <a class="header-anchor" href="#conventions-matched-to-the-tree-walk-and-bytecode" aria-label="Permalink to “Conventions (matched to the tree-walk and bytecode)”">​</a></h2><ul><li><code>Child(n)</code> = nth child of current node: reads <code>node.payload[&quot;children&quot;][n]</code> to get the absolute [<code>AstRef</code>], then calls the child&#39;s compiled function.</li><li><code>Var(&quot;$payload&quot;)</code> reads <code>node.payload</code> as the variable name.</li><li><code>Bind{name: &quot;$payload&quot;, ...}</code> reads <code>node.payload[&quot;name&quot;]</code> as the bind name.</li><li>No-scheme fallback: if a node kind has no eval scheme, returns <code>node.payload</code> directly.</li><li>Closure representation: <code>Value::Object</code> with <code>{&quot;__arrow__&quot;: true, &quot;params&quot;: [...], &quot;body_def&quot;: {&quot;__ast__&quot;: &amp;lt;Ast&gt;}, &quot;binds&quot;?: {...}, &quot;handlers&quot;?: [...]}</code> — self-contained serialized data (ADR-0106), created by the <code>&quot;closure&quot;</code> primitive.</li><li>Primitives: <code>add, sub, mul, div, mod, eq, lt, gt, not, and, or, neg, closure, bind</code> — identical semantics to the tree-walk.</li><li>Scope: <code>Vec&lt;HashMap&lt;String, Value&gt;&gt;</code> scope stack; <code>Bind</code> pushes a child scope; lookup searches innermost-first. Arrow application delegates to the tree-walk engine: an arrow&#39;s <code>body_def</code> arena is minted at runtime, so it is interpreted rather than JIT-compiled.</li></ul><h2 id="safety-model" tabindex="-1">Safety model <a class="header-anchor" href="#safety-model" aria-label="Permalink to “Safety model”">​</a></h2><p>Raw pointers + JIT is inherently unsafe. The safety is encapsulated:</p><ul><li>The public API ([<code>CraneliftEngine</code>], [<code>EvalEngine</code>] impl) is <strong>safe</strong>.</li><li>The [<code>EvalCtx</code>] is owned by the engine on the Rust side; native code receives a raw pointer. The engine guarantees the [<code>EvalCtx</code>] outlives all native code execution.</li><li>[<code>Value</code>] handles are heap-allocated <code>Box&lt;Value&gt;</code> leaked into pointers (<code>Box::into_raw</code>). Helpers that consume a value pointer reclaim the box (<code>Box::from_raw</code> + <code>mem::take</code>). The final return value is reclaimed by the engine. Intermediate values that are checked but not consumed (e.g. a <code>Branch</code> condition) leak for the duration of evaluation — acceptable for Phase 7, documented here. On error, the scope stack and any leaked values are dropped with the [<code>EvalCtx</code>].</li><li><code>Bind</code> scope pop (<code>pop_scope</code>) is only called on the success path. On error, the native code returns immediately, skipping pending <code>pop_scope</code> calls. The scope stack is dropped with the [<code>EvalCtx</code>] on error — no memory corruption, just extra scopes that are never popped. This is a documented safety tradeoff for Phase 7.</li></ul><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="hnl-engine-exec-cranelift-2" tabindex="-1"><a href="./hnl_engine_exec_cranelift.html"><code>hnl_engine_exec_cranelift</code></a> <a class="header-anchor" href="#hnl-engine-exec-cranelift-2" aria-label="Permalink to “hnl_engine_exec_cranelift”">​</a></h3><p><em>1 type alias, 2 modules, 60 functions, 8 constants, 8 structs</em></p><h3 id="craneliftengine" tabindex="-1"><a href="./CraneliftEngine.html"><code>CraneliftEngine</code></a> <a class="header-anchor" href="#craneliftengine" aria-label="Permalink to “CraneliftEngine”">​</a></h3><p><em>5 functions</em></p><h3 id="evalctx" tabindex="-1"><a href="./EvalCtx.html"><code>EvalCtx</code></a> <a class="header-anchor" href="#evalctx" aria-label="Permalink to “EvalCtx”">​</a></h3><p><em>1 function</em></p><h3 id="compile" tabindex="-1"><a href="./compile.html"><code>compile</code></a> <a class="header-anchor" href="#compile" aria-label="Permalink to “compile”">​</a></h3><p><em>1 type alias, 14 functions, 2 enums, 5 structs</em></p><h3 id="standalone" tabindex="-1"><a href="./standalone.html"><code>standalone</code></a> <a class="header-anchor" href="#standalone" aria-label="Permalink to “standalone”">​</a></h3><p><em>1 struct, 12 functions</em></p>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};